Since the variables correspond to the generators of $H$ taken in increasing order, there is only a short list of  possible binomials in $\mathcal{H}$: 
\begin{eqnarray*}
p_0=x_2x_5 -x_3x_4, \quad p_1=x_3^2-x_2x_4, \quad p_2=x_3^2-x_2x_5, \\ 
p_3 = x_4^2-x_2 x_5,\quad p_4=x_4^2-x_3x_5. \quad \quad\quad \quad
\end{eqnarray*}

Assume 
\begin{equation} 2 a_2= u a_1 + a_3 \text{ with }u \geq 1.
\end{equation}

Each of these relations produces a binomial in $I_H$:
\begin{eqnarray*}
f_1     &=& x_1 x_{n+2}- \prod_{j=2}^{n+1}x_j, \\ 
f_i     &=& x_i x_{n+2}- x_1^{(\sum_{j=1}^{i-1}u_j) -1} \prod_{j=i+1}^{n+1} x_j, \text{ for } 2\leq i \leq n+1, \text{ and} \\
f_{n+2} &=& x_{n+2}^2- x_1^{(\sum_{j=1}^n u_j)-2} \prod_{j=2}^n x_j.
\end{eqnarray*}

If $h_2=6$, then $I_H^*$ is a complete intersection, hence  $H$ is $G$-quadratic.
\end{itemize}
This finishes the proof of the theorem.

By Theorem \ref{thm:bounds} we see that 
\begin{equation}
4<a_1< 16.
\end{equation}

Since   $a_1<a_2<\dots <a_5$,  the only possibility for \eqref{eq:sum-cm} is
\begin{equation} a_2+a_3+a_4=  a_1+a_5.
\end{equation}

Then  
			\begin{equation}
			2 a_3= u' a_1 + v' a_2 \text{ with } v' \in \{0, 1\}.
			\end{equation}

Then 
\begin{equation*}
2a_3= u' a_1+ v' a_2+a_4 \text{ with } v'\in \{0,1\}.
\end{equation*}

Therefore $v'=0$ and
\begin{equation} 2a_3= u' a_1+  a_4 \text{ with } u' >0.
\end{equation} 
Consider the normalized expression \eqref{eq:a4-normalized}
\begin{equation*}
									2a_4= u'' a_1 + v'' a_2 + w'' a_3 +\lambda'' a_5.
\end{equation*}

Assume 
\begin{equation} 2 a_2= u a_1 + a_4, \text{  with }u \geq 1.
\end{equation}

Then $u'>0$ and \eqref{eq:a3-normalized} becomes
	\begin{equation}
		2 a_3= u' a_1.
	\end{equation}
 From this and \eqref{eq:case-b} we get $a_3=u'a_1/2$, $a_4=2a_2-u a_1$ and that $a_1$ is even and $u'$ is odd.

By \eqref{eq:case-b} and \eqref{eq:new-new-a3} we may write
			\begin{eqnarray*}
				2 a_5 &=& 2a_2+ 2a_3+2a_4-2a_1 \\
				      &=& (u a_1+a_4) + (u'a_1+v' a_2 +a_4) + (u''a_1+v''a_2+w'' a_3)-2a_1 \\
							&=& (u+u'+u''-2) a_1+ (v'+v'')a_2 +w'' a_3 +2a_4.
			\end{eqnarray*}

If \underline{$w''=1$ and $v'=v''=0$}, summing the equations
			    \begin{eqnarray*}
							2a_4 &=& u'' a_1+ a_3 \\
							2 a_3 &=& u' a_1 +a_4
					\end{eqnarray*}
					we obtain that $a_3+a_4=(u'+u'')a_1$, which, together with \eqref{eq:sum} yields  $a_5=(u'+u''-1)a_1+a_2 \in \langle a_1, a_2 \rangle$, a contradiction.

If \underline{$v''=1$}, then $3a_2=(2u+u'') a_1$ which implies  $3 \nmid 2u+u''$ and  $3|a_1$.
			We get 
			\begin{eqnarray*}
				a_2 &=& \frac{2u+u''}{3} \cdot a_1, \\
				a_4 &=& 2a_2-u= \frac{2u''+u}{3} \cdot a_1.
			\end{eqnarray*}
			By \eqref{eq:sum} we see that  $a_5=a_2+a_3+a_4-a_1= (u+u''-1) a_1+ a_3$, which is false.
			\end{enumerate}
		 \end{enumerate}
The proof of Theorem \ref{thm:5-quad-non-cm} is now complete. $\square$
